import json, sys, html as _h

BOOK = {'title': 'Momotaro, the Peach Boy', 'author': 'Traditional (Japanese folk tale)', 'genre': 'Japanese Folk Tales', 'chapters': [{'n': 1, 'title': 'Complete Text', 'text': "Long ago there lived an old man and an old woman in a village. They had no children. One day the old woman was washing clothes in the river when a great peach came floating down. She carried it home, and when they cut it open, out sprang a beautiful boy. They named him Momotaro, Child of the Peach, and raised him lovingly. He grew strong and brave. When he was fifteen, he heard that ogres on Ogre Island were terrorizing the land. 'I will go and conquer them,' he said. His foster parents gave him millet dumplings for the journey. On the way he met a dog, a monkey, and a pheasant; to each he gave half a dumpling, and each joined him. They crossed to Ogre Island in a boat. The ogres fought fiercely, but the dog bit them, the monkey scratched them, the pheasant pecked their eyes, and Momotaro struck down their chief. The ogres surrendered, gave up their treasure, and promised never to trouble men again. Momotaro returned home laden with gold and jewels, and he and his old parents lived happily ever after."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

